      // SHARED DATA MEMORY (hoisted from /instr to |fetch).
      // One load/store port. At most one memory instruction per group is
      // guaranteed by the $mem_haz slot-1 replay, so a simple 2:1 mux
      // selects the (at most one) memory operation of the group.

      //_@3
         assign FETCH_dm_slot1_a3 = ! L1_FETCH_Instr[0].L1_ld_st_cond_a3;   // The group's memory op (if any) is in slot 1.
         assign FETCH_dm_spec_ld_a3 = L1_FETCH_Instr[0].L1_spec_ld_a3 || L1_FETCH_Instr[1].L1_spec_ld_a3;
         assign FETCH_dm_addr_a3[31:0]     = FETCH_dm_slot1_a3 ? L1_FETCH_Instr[1].L1_addr_a3     : L1_FETCH_Instr[0].L1_addr_a3;
         assign FETCH_dm_valid_st_a3       = L1_FETCH_Instr[0].L1_valid_st_a3 || L1_FETCH_Instr[1].L1_valid_st_a3;
         assign FETCH_dm_st_value_a3[31:0] = FETCH_dm_slot1_a3 ? L1_FETCH_Instr[1].L1_st_value_a3 : L1_FETCH_Instr[0].L1_st_value_a3;
         assign FETCH_dm_st_mask_a3[3:0]   = FETCH_dm_slot1_a3 ? L1_FETCH_Instr[1].L1_st_mask_a3  : L1_FETCH_Instr[0].L1_st_mask_a3;
      //_@5
         // A simple array memory (as in the original), placed in the fetch pipeline.
         for (bank = 0; bank <= 3; bank++) begin : L1_FETCH_Bank //_/bank

            // For $dm_addr.
            logic [31:0] L1_dm_addr_a5;

            // For $dm_spec_ld.
            logic L1_dm_spec_ld_a5;

            // For $dm_st_mask.
            logic [3:0] L1_dm_st_mask_a5;

            // For $dm_st_value.
            logic [31:0] L1_dm_st_value_a5;

            // For $dm_valid_st.
            logic L1_dm_valid_st_a5;

            // For $ld_data.
            logic [(32 / 4) - 1 : 0] L1_ld_data_a5;

            // Explicit pulls of the memory-port signals from |fetch into /bank
            // (replaces the original's $ANY pull, which pulled from /instr).
            assign L1_dm_spec_ld_a5        = FETCH_dm_spec_ld_a5;
            assign L1_dm_addr_a5[31:0]     = FETCH_dm_addr_a5;
            assign L1_dm_valid_st_a5       = FETCH_dm_valid_st_a5;
            assign L1_dm_st_mask_a5[3:0]   = FETCH_dm_st_mask_a5;
            assign L1_dm_st_value_a5[31:0] = FETCH_dm_st_value_a5;
            //_/mem
            //_?$dm_spec_ld
               assign L1_ld_data_a5[(32 / 4) - 1 : 0] = L1b_FETCH_Bank[bank].L1_Mem_Value_a5[L1_dm_addr_a5[4 + 2 : 2]];
         end
         // Combine $ld_data per bank, assuming little-endian.
         assign FETCH_dm_ld_data_a5[31:0] = {L1_FETCH_Bank[3].L1_ld_data_a5, L1_FETCH_Bank[2].L1_ld_data_a5, L1_FETCH_Bank[1].L1_ld_data_a5, L1_FETCH_Bank[0].L1_ld_data_a5};
         // =====
         // Store
         // =====
         for (bank = 0; bank <= 3; bank++) begin : L1b_FETCH_Bank //_/bank

            // For /mem$Value.
            logic [(32 / 4) - 1 : 0] L1_Mem_Value_a5 [31:0];

            /*SV_plus*/
               always @ (posedge clk) begin
                  if (L1_FETCH_Bank[bank].L1_dm_valid_st_a5 && L1_FETCH_Bank[bank].L1_dm_st_mask_a5[bank])
                     L1_Mem_Value_a5[L1_FETCH_Bank[bank].L1_dm_addr_a5[4 + 2 : 2]][(32 / 4) - 1 : 0] <= L1_FETCH_Bank[bank].L1_dm_st_value_a5[(bank + 1) * (32 / 4) - 1: bank * (32 / 4)];
               end
         end
     
      // SHARED ARCHITECTURAL REGISTER FILE (hoisted from /instr to |fetch).
      // Four read ports (2 sources x 2 slots, via /regs[$reg] references in
      // the per-slot Reg Rd logic) and TWO write ports. When both slots
      // commit a write to the SAME register in the same cycle, slot 1
      // (younger, later in program order) wins. (With the conservative WAW
      // replay above this same-register case cannot actually arise, but the
      // priority is kept for safety/clarity.)

      //_@5
         /* verilator lint_save */
         /* verilator lint_on WIDTH */
         for (regs = 1; regs <= 31; regs++) begin : L1_FETCH_Regs //_/regs

            // For $wr0.
            logic L1_wr0_a5;

            // For $wr1.
            logic L1_wr1_a5;

            assign L1_wr0_a5 = L1_FETCH_Instr[0].L1_commit_dest_reg_a5 && (L1_FETCH_Instr[0].L1_wr_reg_a5 == regs);
            assign L1_wr1_a5 = L1_FETCH_Instr[1].L1_commit_dest_reg_a5 && (L1_FETCH_Instr[1].L1_wr_reg_a5 == regs);
            assign FETCH_Regs_value_a4[regs][31:0] = L1_wr1_a5 ? L1_FETCH_Instr[1].L1_rslt_a5 :
                              L1_wr0_a5 ? L1_FETCH_Instr[0].L1_rslt_a5 :
                                     FETCH_Regs_value_a5[regs];
            // Write $pending along with $value, but coded differently because it must be reset.
            assign FETCH_Regs_pending_a4[regs] = ! FETCH_reset_a5 && (L1_wr1_a5 ? L1_FETCH_Instr[1].L1_reg_wr_pending_a5 :
                                             L1_wr0_a5 ? L1_FETCH_Instr[0].L1_reg_wr_pending_a5 :
                                                    FETCH_Regs_pending_a5[regs]);
         end
         /* verilator lint_restore */

   // Visualization for the DUAL-ISSUE hierarchy.
   //_|fetch
      //_@5
         

         for (instr_mem = 0; instr_mem <= 31; instr_mem++) begin : L1b_FETCH_InstrMem //_/instr_mem
            
         end

         for (instr = 0; instr <= 1; instr++) begin : L1b_FETCH_Instr //_/instr

            // For /orig_load_inst$pc.
            logic [31:0] L1_OrigLoadInst_pc_a5;

            // For /src$unconditioned_is_reg.
            logic L1_Src_unconditioned_is_reg_a5 [2:1];

            // For /src$unconditioned_reg.
            logic [4:0] L1_Src_unconditioned_reg_a5 [2:1];

            // For /src$unconditioned_reg_value.
            logic [31:0] L1_Src_unconditioned_reg_value_a5 [2:1];


            // VIZ-support signals (TLV)
            for (src = 1; src <= 2; src++) begin : L2c_Src //_/src
               assign L1_Src_unconditioned_reg_a5[src][4:0] = L1_FETCH_Instr[instr].L2_Src[src].L2_reg_a5;
               assign L1_Src_unconditioned_is_reg_a5[src] = L1_FETCH_Instr[instr].L2_Src[src].L2_is_reg_a5;
               assign L1_Src_unconditioned_reg_value_a5[src][31:0] = L1_FETCH_Instr[instr].L2b_Src[src].L2_reg_value_a5;
            end
            // The original PC of a returning load, for VIZ (the generated VIZ used
            // /orig_inst$pc). Same mux style as the other /orig_load_inst pulls.
            //_/orig_load_inst
               assign L1_OrigLoadInst_pc_a5[31:0] = L1_FETCH_Instr[instr].L1_ld_ret_s1_a5 ? L1_FETCH_Instr[1].L1_pc_a10 : L1_FETCH_Instr[0].L1_pc_a10;
            
         end

         //_/csr_viz
            

         for (regs = 1; regs <= 31; regs++) begin : L1b_FETCH_Regs //_/regs
            
         end

         for (mem = 0; mem <= 31; mem++) begin : L1_FETCH_Mem //_/mem
            
         end

         for (bank = 0; bank <= 3; bank++) begin : L1c_FETCH_Bank //_/bank
            
            for (mem = 0; mem <= 31; mem++) begin : L2b_Mem //_/mem
               
            end
         end

//_\SV
   endmodule


